"""Monthly report helpers: per-category summaries and duplicate detection."""

from datetime import date


def _parse_month(month):
    """Parse a "YYYY-MM" string into (year, month) ints."""
    try:
        year_s, month_s = month.split("-")
        if len(year_s) != 4 or len(month_s) != 2:
            raise ValueError
        year, mon = int(year_s), int(month_s)
        date(year, mon, 1)  # validates the month range
    except (ValueError, AttributeError):
        raise ValueError(f"invalid month {month!r}; expected YYYY-MM") from None
    return year, mon


def in_month(transactions, month):
    """Return the transactions dated in the given "YYYY-MM" calendar month."""
    year, mon = _parse_month(month)
    return [t for t in transactions if t.day.year == year and t.day.month == mon]


def summarize(transactions, month):
    """Map category -> net total (2 decimals) for the month, omitting zero totals."""
    totals = {}
    for t in in_month(transactions, month):
        totals[t.category] = totals.get(t.category, 0.0) + t.amount
    result = {}
    for category, total in totals.items():
        rounded = round(total, 2)
        if rounded != 0:
            result[category] = rounded + 0.0  # normalise -0.0
    return result


def _cents(amount):
    return round(amount * 100)


def find_duplicates(transactions):
    """Return (earlier_id, later_id) pairs with same payee and amount within 2 days.

    Refunds (negative amounts) are never considered duplicates. The result is
    sorted by the earlier transaction's date, then its id.
    """
    candidates = sorted(
        (t for t in transactions if t.amount >= 0),
        key=lambda t: (t.day, t.id),
    )
    pairs = []
    for i, a in enumerate(candidates):
        for b in candidates[i + 1:]:
            if (b.day - a.day).days > 2:
                break
            if a.payee == b.payee and _cents(a.amount) == _cents(b.amount):
                pairs.append(((a.day, a.id, b.day, b.id), (a.id, b.id)))
    pairs.sort(key=lambda p: p[0])
    return [p[1] for p in pairs]
